-- 0445 PROD CHECK, BEFORE the deploy (and after it): every hunk 0445 cuts occurs EXACTLY ONCE in the live body it cuts, nothing of 0445 is there yet,
-- and the self-assert probe's SELECTION (CLAUDE.md: a migration's selections run read-only on prod first). GENERATED by gen-checks.mjs.
--   npx --yes supabase@2.120.0 db query --linked --output-format json -f scripts/ops/harness/pirates-at-sea/hunks.sql
-- Run scripts/ops/harness/db-health/gate.sql first. ONE statement, read-only: the catalog (pg_get_functiondef of six functions), public.world_config by
-- key, and public.pirate_ships (~121 rows) with each one's fleet and ships by key; stable functions only (public.pirate_ord_wanted, public.pirate_haunt_of).
-- BEFORE, wanted: ok true (every `n` 1); applied false; knobs.pirate_strike_tries_per_run 8; probe.fleet not null (a pirate lying free in a harbour,
--   her ord wanted, a haunt in reach of her home: the probe borrows her inside a block it rolls back).
-- AFTER, wanted: applied true; hunks {pirate_ship_step 1: 0, pirate_ship_step 2: 0, pirate_ship_step 3: 0, pirate_strike 1: 0, pirate_strikes 1: 1, pirate_trade 1: 0, tick_pirates 1: 0, tick_pirates 2: 0, tick_pirates 3: 0, battle_join_near 1: 0} (an old text that stands inside its new text still counts 1).
begin transaction read only;
with h (fn, ord, old) as (values
  ('public.pirate_ship_step(uuid,timestamp with time zone)', 1, $h$      if p_now < n.haunt_since + make_interval(hours => public.wc_int('pirate_haunt_hours')) then
        return 'HAUNT';
      end if;
    end if;
$h$),
  ('public.pirate_ship_step(uuid,timestamp with time zone)', 2, $h$  select * into h from public.pirate_haunt_of(n.home_port, n.ord);
$h$),
  ('public.pirate_ship_step(uuid,timestamp with time zone)', 3, $h$  return public.pirate_sail(p_fleet, f.port_id, voyage.segments_from_course(h.course), h.port_id, h.sea_id, h.port_id, 'CRUISE', p_now);
$h$),
  ('public.pirate_strike(uuid,timestamp with time zone)', 1, $h$c.fleet_id = p_fleet and f.busy_until is null) then
$h$),
  ('public.pirate_strikes(timestamp with time zone)', 1, $h$                where f.busy_until is null
$h$),
  ('public.pirate_trade(uuid,uuid,timestamp with time zone)', 1, $h$  if public.wc('pirates_trade') is distinct from 'true'::jsonb or not public.city_treasury_on() then
$h$),
  ('public.tick_pirates(timestamp with time zone)', 1, $h$  v_paid  bigint := 0;
begin
$h$),
  ('public.tick_pirates(timestamp with time zone)', 2, $h$    exit when v_n >= v_max or current_setting('byeharu.pirate_traded', true) = 'on';   -- 0415: a ship that traded holds the market rows and the purse of her harbour until this run commits, so the run steps no more ships after her (the rest go next minute; the order turns)
    v_n := v_n + 1;
$h$),
  ('public.tick_pirates(timestamp with time zone)', 3, $h$jsonb_build_object('joined', public.battle_npc_joins(p_now)) else '{}'::jsonb end;
end
$h$),
  ('public.battle_join_near(uuid,text,timestamp with time zone)', 1, $h$              from (select f.id, voyage.gc_distance_nm(v_lat, v_lon, (a.lat + (z.lat - a.lat) * w.k)::float8, (a.lon + (z.lon - a.lon) * w.k)::float8)::numeric as nm
$h$)
), body as (
  select f.fn, replace(pg_get_functiondef(f.fn::regprocedure), E'\r', '') as def
    from (values ('public.pirate_ship_step(uuid,timestamp with time zone)'), ('public.pirate_strike(uuid,timestamp with time zone)'), ('public.pirate_strikes(timestamp with time zone)'), ('public.pirate_trade(uuid,uuid,timestamp with time zone)'), ('public.tick_pirates(timestamp with time zone)'), ('public.battle_join_near(uuid,text,timestamp with time zone)')) f(fn)
), n as (
  select h.fn, h.ord, (length(b.def) - length(replace(b.def, h.old, ''))) / length(h.old) as n from h join body b on b.fn = h.fn
), pr as (
  select x.fleet_id, x.ord, p.code as home, f.status
    from public.pirate_ships x join public.fleets f on f.id = x.fleet_id join public.ports p on p.id = x.home_port
   where x.laid_up_at is null and x.unpaid_since is null and x.wrecked_at is null and f.status = 'DOCKED' and f.busy_until is null
     and public.pirate_ord_wanted(x.ord)
     and exists (select 1 from public.ships s where s.fleet_id = x.fleet_id and s.durability > 0)
     and exists (select 1 from public.pirate_haunt_of(x.home_port, x.ord))
   order by x.ord limit 1
)
select jsonb_build_object(
  'at', now(),
  'head', (select max(m.version) from supabase_migrations.schema_migrations m),
  'ok', (select bool_and(n.n = 1) from n),
  'hunks', (select jsonb_agg(jsonb_build_object('fn', n.fn, 'ord', n.ord, 'n', n.n) order by n.fn, n.ord) from n),
  'bodies', (select jsonb_object_agg(b.fn, md5(b.def)) from body b),
  'applied', to_regprocedure('public.pirate_cruise_plan(uuid,uuid)') is not null,
  'knobs', (select jsonb_object_agg(w.key, w.value) from public.world_config w
             where w.key in ('pirate_cruise_nm', 'pirate_cruise_courses', 'pirate_port_minutes', 'pirate_refit_below', 'pirate_sails_per_run', 'pirate_strike_from_port',
                             'pirate_strike_tries_per_run', 'pirate_haunt_hours', 'pirates_bite', 'pirates_trade', 'attack_enabled', 'city_treasury_enabled')),
  'probe', (select jsonb_build_object('fleet', pr.fleet_id, 'ord', pr.ord, 'home', pr.home, 'status', pr.status) from pr),
  'pirate_ships', (select count(*) from public.pirate_ships)
) as r;
commit;
